    }
  }

  disconnect() {
    super.disconnect()
    this.notifyBridgeOfDisconnect()
    this.stampObserver?.disconnect()
  }

  notifyBridgeOfConnect() {
    const bridgeElement = this.bridgeElement

    this.send("connect", {
      title: bridgeElement.title,
      description: this.#description(bridgeElement)
    })
  }

  notifyBridgeOfDisconnect() {
    this.send("disconnect")
  }

  #description(bridgeElement) {
    const timestamp = bridgeElement.bridgeAttribute("description-timestamp")

    if (timestamp) {
      const date = new Date(timestamp)
      if (!Number.isNaN(date.getTime())) return formatLocalTime(date, "date_with_year")
    }

    return bridgeElement.bridgeAttribute("description")
  }

  #observeStamp() {
    this.stampObserver = new MutationObserver(() => {
      this.notifyBridgeOfConnect()
    })

    this.stampObserver.observe(this.element, {
      attributes: true
    })
  }
}
